from fractions import Fraction as Fr

def cand():
    out = set()
    e = Fr(1, 10**7)
    for a in range(-14, 15):
        for b in range(-30, 31):
            for c in range(-60, 61):
                F = lambda t: t**3 + a*t*t + b*t + c
                # (가): x->0+, 3+ 에서 유한
                ok = True
                for p in (0, 3):
                    u = p + e
                    if abs(F(u)/(u*(u - 3))) > 10**4:
                        ok = False
                        break
                if not ok:
                    continue
                if F(0) != 0 or F(3) != 0:
                    continue
                # 세 번째 근이 정수인 실근
                for t in [r for r in real_roots(Poly(F(Symbol('x')), Symbol('x')))]:
                    if t <= 0:
                        continue
                    t = Rational(t)
                    cnt = 0
                    for m in range(1, 80):
                        u = Fr(m) + e
                        gv = (-F(u)) if u < t else F(u)
                        if gv/(u*(u - 3)) < 0:
                            cnt += 1
                    if cnt == 3:
                        out.add(F(7))
    return out

def skill():
    k = 6
    return 7*(7 - 3)*(7 - k)

def standard():
    v = cand()
    assert len(v) == 1
    return list(v)[0]

def unique():
    return sorted(cand())
